import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Locale;

public class knucleotide {
    private static final String[] FRAGMENTS = {
        "GGT", "GGTA", "GGTATT", "GGTATTTTAATT", "GGTATTTTAATTTATAGT"
    };
    private static final char[] BASES = {'A', 'C', 'G', 'T'};

    private static int encodeBase(char c) {
        switch (c) {
            case 'A': case 'a': return 0;
            case 'C': case 'c': return 1;
            case 'G': case 'g': return 2;
            case 'T': case 't': return 3;
            default: return -1;
        }
    }

    private static long encodeFragment(String fragment) {
        long value = 0;
        for (int i = 0; i < fragment.length(); i++) {
            value = (value << 2) | encodeBase(fragment.charAt(i));
        }
        return value;
    }

    private static void appendFrequencies(
            StringBuilder output, long[] counts, int k) {
        Integer[] order = new Integer[counts.length];
        long total = 0;

        for (int i = 0; i < counts.length; i++) {
            order[i] = i;
            total += counts[i];
        }

        Arrays.sort(order, (a, b) -> {
            int comparison = Long.compare(counts[b], counts[a]);
            return comparison != 0 ? comparison : Integer.compare(a, b);
        });

        for (int key : order) {
            if (counts[key] == 0) {
                break;
            }

            char[] word = new char[k];
            int value = key;
            for (int i = k - 1; i >= 0; i--) {
                word[i] = BASES[value & 3];
                value >>>= 2;
            }

            output.append(word).append(' ');
            output.append(String.format(
                Locale.US, "%.3f", counts[key] * 100.0 / total));
            output.append('\n');
        }
        output.append('\n');
    }

    public static void main(String[] args) throws Exception {
        int n = Integer.parseInt(args[0]);

        long[] singleCounts = new long[4];
        long[] pairCounts = new long[16];
        long[] fragmentCounts = new long[FRAGMENTS.length];

        final long target0 = encodeFragment(FRAGMENTS[0]);
        final long target1 = encodeFragment(FRAGMENTS[1]);
        final long target2 = encodeFragment(FRAGMENTS[2]);
        final long target3 = encodeFragment(FRAGMENTS[3]);
        final long target4 = encodeFragment(FRAGMENTS[4]);

        final long mask0 = (1L << 6) - 1;
        final long mask1 = (1L << 8) - 1;
        final long mask2 = (1L << 12) - 1;
        final long mask3 = (1L << 24) - 1;
        final long mask4 = (1L << 36) - 1;

        long rolling = 0;
        int available = 0;
        boolean readingThree = false;

        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in, StandardCharsets.US_ASCII),
                1 << 16)) {
            String line;

            while ((line = reader.readLine()) != null) {
                if (line.isEmpty()) {
                    continue;
                }

                char first = line.charAt(0);
                if (first == '>') {
                    if (readingThree) {
                        break;
                    }
                    readingThree = line.startsWith(">THREE");
                    continue;
                }

                if (!readingThree || first == ';') {
                    continue;
                }

                for (int i = 0; i < line.length(); i++) {
                    char c = line.charAt(i);
                    int base = encodeBase(c);

                    if (base < 0) {
                        if (!Character.isWhitespace(c)) {
                            rolling = 0;
                            available = 0;
                        }
                        continue;
                    }

                    rolling = (rolling << 2) | base;
                    if (available < 18) {
                        available++;
                    }

                    singleCounts[base]++;
                    if (available >= 2) {
                        pairCounts[(int) (rolling & 15)]++;
                    }

                    if (available >= 3 && (rolling & mask0) == target0) {
                        fragmentCounts[0]++;
                    }
                    if (available >= 4 && (rolling & mask1) == target1) {
                        fragmentCounts[1]++;
                    }
                    if (available >= 6 && (rolling & mask2) == target2) {
                        fragmentCounts[2]++;
                    }
                    if (available >= 12 && (rolling & mask3) == target3) {
                        fragmentCounts[3]++;
                    }
                    if (available >= 18 && (rolling & mask4) == target4) {
                        fragmentCounts[4]++;
                    }
                }
            }
        }

        StringBuilder output = new StringBuilder(512);
        appendFrequencies(output, singleCounts, 1);
        appendFrequencies(output, pairCounts, 2);

        for (int i = 0; i < FRAGMENTS.length; i++) {
            output.append(fragmentCounts[i])
                  .append('\t')
                  .append(FRAGMENTS[i])
                  .append('\n');
        }

        System.out.print(output);
    }
